// src/juice/Celebration.tsx — the confetti burst for ceremony v2, streak, and legendary moments.
//
// The animation is an original hand-authored Lottie (assets/juice/confetti.lottie.json, generated by
// content/scripts/build-confetti.ts — no third-party asset). It is purely decorative, so it is hidden
// from the accessibility tree.
//
// Reduce-motion (GC-10): when motion is reduced we render NO Lottie at all — instead a static
// congratulatory frame (a still row of the same accent-colored confetti shapes), so the celebration
// still reads without any animation.

import { View } from 'react-native';
import LottieView from 'lottie-react-native';

import { useReduceMotion } from '@/design/motion';
import { colors } from '@/design/tokens';

import confetti from '../../assets/juice/confetti.lottie.json';

const STATIC_COLORS = [colors.clay400, colors.xpGold, colors.gemTeal, colors.streakFlame, colors.success];

export interface CelebrationProps {
  /** Whether the burst should be playing. */
  play?: boolean;
  /** Loop the confetti (defaults to a single burst). */
  loop?: boolean;
  size?: number;
}

/** A full-bleed decorative confetti overlay. Absolute-positioned; never intercepts touches. */
export function Celebration({ play = true, loop = false, size = 260 }: CelebrationProps) {
  const reduceMotion = useReduceMotion();

  if (reduceMotion) {
    // Static congratulatory frame — a still scatter of confetti shapes, no motion.
    return (
      <View
        pointerEvents="none"
        accessibilityElementsHidden
        importantForAccessibility="no-hide-descendants"
        testID="celebration-static"
        style={{ flexDirection: 'row', gap: 8, justifyContent: 'center' }}
      >
        {STATIC_COLORS.map((c, i) => (
          <View
            key={c}
            style={{
              width: 12,
              height: 18,
              borderRadius: 2,
              backgroundColor: c,
              transform: [{ rotate: `${(i - 2) * 12}deg` }],
            }}
          />
        ))}
      </View>
    );
  }

  return (
    <View
      pointerEvents="none"
      accessibilityElementsHidden
      importantForAccessibility="no-hide-descendants"
      testID="celebration-lottie"
      style={{ width: size, height: size, alignItems: 'center', justifyContent: 'center' }}
    >
      <LottieView source={confetti} autoPlay={play} loop={loop} style={{ width: size, height: size }} />
    </View>
  );
}
